// 提取内容数据
const data = $input.first().json;
const results = data.results || [];

if (results.length === 0) {
  throw new Error('没有待发布的小红书内容');
}

const items = [];
for (const page of results) {
  const props = page.properties;
  items.push({
    json: {
      pageId: page.id,
      contentId: props['内容ID']?.rich_text?.[0]?.text?.content || '',
      title: props['标题']?.title?.[0]?.text?.content || '无标题',
      content: props['正文']?.rich_text?.[0]?.text?.content || '',
      tags: props['话题标签']?.multi_select?.map(t => t.name) || [],
      images: props['配图列表']?.rich_text?.[0]?.text?.content?.split('\n') || [],
      platform: '小红书',
      timestamp: new Date().toISOString()
    }
  });
}

return items;

// 准备小红书发布数据
const d = $json;

// 格式化标签（小红书格式：#标签）
const formattedTags = d.tags.map(t => `#${t}`).join(' ');

// 组合完整内容
const fullContent = `${d.title}\n\n${d.content}\n\n${formattedTags}`;

return [{
  json: {
    ...d,
    fullContent: fullContent,
    publishData: {
      title: d.title,
      desc: fullContent,
      type: 'normal',  // 普通笔记
      post_time: Math.floor(Date.now() / 1000)  // 立即发布
    }
  }
}];

// 注意：小红书官方API需要企业认证
// 这里提供两种方案：
// 1. 使用第三方自动化工具（如：小红书自动化插件）
// 2. 人工发布（生成发布预览）

const d = $json;

// 方案2：生成发布预览和指导
const preview = `【小红书发布预览】

标题：${d.title}

内容：
${d.fullContent}

配图建议：
${d.images.map((img, i) => `图${i+1}: ${img}`).join('\n')}

【人工发布步骤】
1. 打开小红书APP
2. 点击

创建笔记
3. 复制上述标题和内容
4. 上传配图
5. 发布

【自动化方案】
如需自动化发布，请配置：
- 小红书开放平台API（企业认证）
- 或使用第三方自动化工具
`;

return [{
  json: {
    ...d,
    publishStatus: '待人工发布',
    publishPreview: preview,
    publishMethod: '人工发布',
    // 如果有API，在这里调用
    // publishResult: await callXiaohongshuAPI(d.publishData)
  }
}];

// 整合发布结果
const d = $json;
const publishId = 'PUB' + Date.now() + Math.random().toString(36).substr(2, 5).toUpperCase();

// 模拟发布链接（实际应该从API返回）
const publishUrl = `https://www.xiaohongshu.com/explore/${publishId.toLowerCase()}`;

return [{
  json: {
    publishId: publishId,
    title: d.title,
    platform: '小红书',
    publishUrl: publishUrl,
    platformContentId: publishId,  // 实际应该从API返回
    contentPageId: d.pageId,
    publishTime: new Date().toISOString(),
    publishMethod: d.publishMethod,
    publishStatus: d.publishStatus === '待人工发布' ? '待人工发布' : '成功',
    publishPreview: d.publishPreview,
    initialData: '阅读0/点赞0/评论0',
    createdAt: new Date().toISOString()
  }
}];

// 构建Notion发布库请求
const d = $json;
const body = {
  parent: { database_id: process.env.NOTION_PUBLISH_DB_ID },
  properties: {
    '标题': { title: [{ text: { content: d.title.substring(0, 100) } }] },
    '发布ID': { rich_text: [{ text: { content: d.publishId } }] },
    '平台': { select: { name: d.platform } },
    '发布链接': { url: d.publishUrl },
    '平台内容ID': { rich_text: [{ text: { content: d.platformContentId } }] },
    '发布时间': { date: { start: d.publishTime } },
    '发布方式': { select: { name: d.publishMethod } },
    '发布状态': { select: { name: d.publishStatus } },
    '初始数据': { rich_text: [{ text: { content: d.initialData } }] }
  }
};
return [{ json: { notionBody: JSON.stringify(body), originalData: d } }];

// 生成执行摘要
const items = $input.first().json.data || [];
const successCount = items.filter(item => item.id).length;

const summary = `小红书发布报告
==================
执行时间: ${new Date().toLocaleString('zh-CN')}

【发布结果】
- 成功: ${successCount}篇
- 失败: ${items.length - successCount}篇

【发布列表】
${items.slice(0, 5).map((item, i) => {
  const d = item.originalData;
  return `${i+1}. ${d?.title}\n   链接: ${d?.publishUrl}\n   状态: ${d?.publishStatus}`;
}).join('\n\n')}

【人工发布预览】
${items.filter(item => item.originalData?.publishPreview).map(item => item.originalData.publishPreview).join('\n---\n')}

【下一步】
1. 如果是

，请按照预览手动发布
2. 发布后更新发布库中的实际链接
3. 24小时后运行数据监测工作流`;

return [{
  json: {
    report: summary,
    successCount,
    totalCount: items.length,
    timestamp: new Date().toISOString()
  }
}];
